func newDynamoDBUpdateTableCmd() *cobra.Command {
	var tableName string
	var attributeDefinitions []string
	var billingMode string
	var deletionProtectionEnabled bool
	var globalSecondaryIndexUpdates string
	var globalTableSettingsReplicationMode string
	var globalTableWitnessUpdates string
	var multiRegionConsistency string
	var onDemandThroughput string
	var provisionedThroughput string
	var replicaUpdates string
	var sSESpecification string
	var streamSpecification string
	var tableClass string
	var warmThroughput string

	cmd := &cobra.Command{
		Use:   "update-table",
		Short: "UpdateTable",
		RunE: func(cmd *cobra.Command, _ []string) error {
			cfg, err := newAWSConfig(cmd.Context())
			if err != nil {
				return err
			}

			client := dynamodb.NewFromConfig(cfg, func(o *dynamodb.Options) {
				o.BaseEndpoint = aws.String(endpointURL)
			})

			input := &dynamodb.UpdateTableInput{}

			if tableName != "" {
				input.TableName = aws.String(tableName)
			}

			for _, raw := range attributeDefinitions {
				var val types.AttributeDefinition
				if err := cligen.SetFieldsFromKV(reflect.ValueOf(&val).Elem(), raw); err != nil {
					return fmt.Errorf("update-table: parse --attribute-definitions: %w", err)
				}
				input.AttributeDefinitions = append(input.AttributeDefinitions, val)
			}

			if billingMode != "" {
				input.BillingMode = types.BillingMode(billingMode)
			}

			if deletionProtectionEnabled {
				input.DeletionProtectionEnabled = aws.Bool(deletionProtectionEnabled)
			}

			if globalSecondaryIndexUpdates != "" {
				if err := json.Unmarshal([]byte(globalSecondaryIndexUpdates), &input.GlobalSecondaryIndexUpdates); err != nil {
					return fmt.Errorf("update-table: parse --global-secondary-index-updates: %w", err)
				}
			}

			if globalTableSettingsReplicationMode != "" {
				input.GlobalTableSettingsReplicationMode = types.GlobalTableSettingsReplicationMode(globalTableSettingsReplicationMode)
			}

			if globalTableWitnessUpdates != "" {
				if err := json.Unmarshal([]byte(globalTableWitnessUpdates), &input.GlobalTableWitnessUpdates); err != nil {
					return fmt.Errorf("update-table: parse --global-table-witness-updates: %w", err)
				}
			}

			if multiRegionConsistency != "" {
				input.MultiRegionConsistency = types.MultiRegionConsistency(multiRegionConsistency)
			}

			if onDemandThroughput != "" {
				var val types.OnDemandThroughput
				if err := cligen.SetFieldsFromKV(reflect.ValueOf(&val).Elem(), onDemandThroughput); err != nil {
					return fmt.Errorf("update-table: parse --on-demand-throughput: %w", err)
				}
				input.OnDemandThroughput = &val
			}

			if provisionedThroughput != "" {
				var val types.ProvisionedThroughput
				if err := cligen.SetFieldsFromKV(reflect.ValueOf(&val).Elem(), provisionedThroughput); err != nil {
					return fmt.Errorf("update-table: parse --provisioned-throughput: %w", err)
				}
				input.ProvisionedThroughput = &val
			}

			if replicaUpdates != "" {
				if err := json.Unmarshal([]byte(replicaUpdates), &input.ReplicaUpdates); err != nil {
					return fmt.Errorf("update-table: parse --replica-updates: %w", err)
				}
			}

			if sSESpecification != "" {
				var val types.SSESpecification
				if err := cligen.SetFieldsFromKV(reflect.ValueOf(&val).Elem(), sSESpecification); err != nil {
					return fmt.Errorf("update-table: parse --sse-specification: %w", err)
				}
				input.SSESpecification = &val
			}

			if streamSpecification != "" {
				var val types.StreamSpecification
				if err := cligen.SetFieldsFromKV(reflect.ValueOf(&val).Elem(), streamSpecification); err != nil {
					return fmt.Errorf("update-table: parse --stream-specification: %w", err)
				}
				input.StreamSpecification = &val
			}

			if tableClass != "" {
				input.TableClass = types.TableClass(tableClass)
			}

			if warmThroughput != "" {
				var val types.WarmThroughput
				if err := cligen.SetFieldsFromKV(reflect.ValueOf(&val).Elem(), warmThroughput); err != nil {
					return fmt.Errorf("update-table: parse --warm-throughput: %w", err)
				}
				input.WarmThroughput = &val
			}

			out, err := client.UpdateTable(cmd.Context(), input)
			if err != nil {
				return fmt.Errorf("update-table failed: %w", err)
			}

			if err := json.NewEncoder(os.Stdout).Encode(out); err != nil {
				return fmt.Errorf("failed to encode output: %w", err)
			}

			return nil
		},
	}

	cmd.Flags().StringVar(&tableName, "table-name", "", "Table name")

	cmd.Flags().StringArrayVar(&attributeDefinitions, "attribute-definitions", nil, "Attribute definitions (key=value,key2=value2, repeatable)")

	cmd.Flags().StringVar(&billingMode, "billing-mode", "", "Billing mode")

	cmd.Flags().BoolVar(&deletionProtectionEnabled, "deletion-protection-enabled", false, "Deletion protection enabled")

	cmd.Flags().StringVar(&globalSecondaryIndexUpdates, "global-secondary-index-updates", "", "Global secondary index updates (JSON)")

	cmd.Flags().StringVar(&globalTableSettingsReplicationMode, "global-table-settings-replication-mode", "", "Global table settings replication mode")

	cmd.Flags().StringVar(&globalTableWitnessUpdates, "global-table-witness-updates", "", "Global table witness updates (JSON)")

	cmd.Flags().StringVar(&multiRegionConsistency, "multi-region-consistency", "", "Multi region consistency")

	cmd.Flags().StringVar(&onDemandThroughput, "on-demand-throughput", "", "On demand throughput (key=value,key2=value2)")

	cmd.Flags().StringVar(&provisionedThroughput, "provisioned-throughput", "", "Provisioned throughput (key=value,key2=value2)")

	cmd.Flags().StringVar(&replicaUpdates, "replica-updates", "", "Replica updates (JSON)")

	cmd.Flags().StringVar(&sSESpecification, "sse-specification", "", "Sse specification (key=value,key2=value2)")

	cmd.Flags().StringVar(&streamSpecification, "stream-specification", "", "Stream specification (key=value,key2=value2)")

	cmd.Flags().StringVar(&tableClass, "table-class", "", "Table class")

	cmd.Flags().StringVar(&warmThroughput, "warm-throughput", "", "Warm throughput (key=value,key2=value2)")

	cmd.Flags().String("region", "", "Region override (ignored)")

	return cmd
}

